import 'dart:convert';
import 'dart:typed_data';

/// Pre-cached in-memory bytes for Chatflow screenshots to ensure reliable rendering across web & desktop
class ChatflowBytes {
  static final Map<String, Uint8List> _cache = {};

  static Uint8List? getBytes(String assetPath) {
    if (_cache.containsKey(assetPath)) return _cache[assetPath];
    final base64Str = _data[assetPath];
    if (base64Str == null) return null;
    final bytes = base64Decode(base64Str);
    _cache[assetPath] = bytes;
    return bytes;
  }

  static final Map<String, String> _data = {
    'assets/images/chatflow_card_banner.png':
        '',
    'assets/images/chatflow_logo.png':
        '',
    'assets/images/chatflow/chatflow_account_settings.png':
        '',
    'assets/images/chatflow/chatflow_auth_login.png':
        '',
    'assets/images/chatflow/chatflow_chat_without_limits.png':
        '',
    'assets/images/chatflow/chatflow_crystal_clear_calling.png':
        '',
    'assets/images/chatflow/chatflow_discovery_moments.png':
        '',
    'assets/images/chatflow/chatflow_messages_inbox.png':
        '',
    'assets/images/chatflow/chatflow_pending_requests.png':
        '',
    'assets/images/chatflow/chatflow_private_by_default.png':
        '',
    'assets/images/chatflow/chatflow_profile_settings.png':
        '',
    'assets/images/chatflow/chatflow_splash.png':
        '',
    'assets/images/chatflow/chatflow_voice_video_calls.png':
        '',
  };
}